import sys
from itertools import combinations

n, k = map(int, sys.stdin.readline().split())
problems = [list(map(int, sys.stdin.readline().split())) for _ in range(n)]

def can_make_interesting_problemset(problems, k):
    for r in range(1, n + 1):
        for subset in combinations(range(n), r):
            if all(sum(problems[i][j] for i in subset) <= k // 2 for j in range(k)):
                return True
    return False

print("YES" if can_make_interesting_problemset(problems, k) else "NO")
